def max_run_uppercase(s):
    if len(s) == 0:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(s)):
        if s[i].isupper() and s[i-1].isupper():
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
            current_len = 1

    return max(max_len, current_len)

